import { InvalidKeyError, RangeNotSatisfiableError } from "./errors.ts";
import type { ByteRange } from "./types.ts";

const SEGMENT = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
const MAX_KEY_LENGTH = 1024;

/**
 * Keys are generated by Hekate, never taken from file names, but every backend
 * still refuses anything that could escape its root: empty or dot segments,
 * absolute paths, backslashes and unusual characters.
 */
export function assertValidKey(key: string): void {
  if (key.length === 0 || key.length > MAX_KEY_LENGTH) {
    throw new InvalidKeyError(`Invalid storage key length: ${key.length}`);
  }
  for (const segment of key.split("/")) {
    if (!SEGMENT.test(segment)) throw new InvalidKeyError(`Invalid storage key: "${key}"`);
  }
}

/** A prefix is a key, or a key followed by `/`, or empty for everything. */
export function assertValidPrefix(prefix: string): void {
  if (prefix === "") return;
  assertValidKey(prefix.endsWith("/") ? prefix.slice(0, -1) : prefix);
}

/** Where an organisation's object lives. One namespace per organisation. */
export function objectKey(organisationId: string, objectId: string): string {
  const key = `org/${organisationId}/${objectId}`;
  assertValidKey(key);
  return key;
}

export function assertValidRange(range: ByteRange): void {
  const { start, end } = range;
  if (!Number.isSafeInteger(start) || start < 0) {
    throw new RangeNotSatisfiableError(`Invalid range start: ${start}`);
  }
  if (end !== undefined && (!Number.isSafeInteger(end) || end < start)) {
    throw new RangeNotSatisfiableError(`Invalid range end: ${end}`);
  }
}
